package com.velora.api.config;
import com.velora.api.entity.*;import com.velora.api.repository.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.security.crypto.password.PasswordEncoder;import java.util.*;
@Configuration public class DataInitializer {
 @Bean CommandLineRunner seed(UserRepository users,ProductRepository products,CategoryRepository categories,PasswordEncoder encoder,@Value("${app.admin.email}") String adminEmail,@Value("${app.admin.password}") String adminPassword){return args->{String email=adminEmail.trim().toLowerCase();if(users.findByEmail(email).isEmpty()){User u=new User();u.setName("VELORA Admin");u.setEmail(email);u.setPasswordHash(encoder.encode(adminPassword));u.setRole(Role.ADMIN);users.save(u);}if(categories.count()==0){for(String n:List.of("New Arrivals","Clothing","Outerwear","Accessories","Footwear")){Category c=new Category();c.setName(n);c.setSlug(n.toLowerCase().replaceAll("[^a-z0-9]+","-"));categories.save(c);}}if(products.count()==0){String[][] seed={{"Sculpted Wool Coat","outerwear","349900","https://images.unsplash.com/photo-1539533018447-63fcce2678e3?auto=format&fit=crop&w=1000&q=85"},{"Everyday Tailored Shirt","clothing","89900","https://images.unsplash.com/photo-1598033129183-c4f50c736f10?auto=format&fit=crop&w=1000&q=85"},{"Structured Leather Tote","accessories","159900","https://images.unsplash.com/photo-1584917865442-de89df76afd3?auto=format&fit=crop&w=1000&q=85"},{"Minimal Leather Sneaker","footwear","129900","https://images.unsplash.com/photo-1549298916-b41d501d3772?auto=format&fit=crop&w=1000&q=85"},{"Relaxed Linen Set","clothing","119900","https://images.unsplash.com/photo-1483985988355-763728e1935b?auto=format&fit=crop&w=1000&q=85"},{"Modern Weekend Jacket","outerwear","189900","https://images.unsplash.com/photo-1551028719-00167b16eac5?auto=format&fit=crop&w=1000&q=85"}};for(int i=0;i<seed.length;i++){Product p=new Product();p.setName(seed[i][0]);p.setSlug(seed[i][0].toLowerCase().replaceAll("[^a-z0-9]+","-"));p.setCategory(seed[i][1]);p.setPricePaise(Long.parseLong(seed[i][2]));p.setImageUrl(seed[i][3]);p.setDescription("Considered design, elevated materials and everyday versatility. Made to be worn on repeat.");p.setSizes("XS,S,M,L,XL");p.setColors("Black,Stone,Olive");p.setStock(25);p.setFeatured(i<4);products.save(p);}}};}
}
